function renderDetail(){const p=state.reservoir.points[state.selectedIndex],pressure=pressureAt(p),margin=state.limit-pressure,use=Math.max(0,pressure/state.limit*100),maxRate=state.rate*state.limit/Math.max(pressure,.01),projectCount=1+Number(state.betaEnabled)+Number(state.zetaEnabled);$('selectedName').textContent=`Cell ${state.selectedIndex+1}`;$('budgetValue').textContent=`${fmt(use,0)}%`;$('budgetBar').style.width=`${Math.min(100,use)}%`;$('budgetBar').style.background=use>100?'#d26055':use>75?'#d09e58':'#dec16b';$('budgetCaption').textContent=use>100?'Configured pressure constraint exceeded in this screening case.':`${fmt(Math.max(0,100-use),0)}% of the configured pressure headroom remains.`;$('pressureValue').textContent=`+${fmt(pressure)} bar`;$('pressureContext').textContent=`P${state.percentile} · year ${state.year}`;$('marginValue').textContent=`${margin>=0?'+':'−'}${fmt(Math.abs(margin))} bar`;$('injectionCost').textContent=`+${fmt(pressure*.78,0)}%`;$('productionCost').textContent=`−${fmt(pressure*.41,0)}%`;$('maxRate').textContent=`${fmt(Math.min(9.9,maxRate))} Mt/yr`;$('bindingConstraint').textContent=use>78?'Pressure headroom':projectCount>1?'Project interference':'Geothermal receptor';$('envelopeTitle').textContent=use>100?'Scenario exceeds the configured screening envelope':use>78?'Scenario approaches a binding constraint':'Scenario remains inside the screening envelope';$('envelopeText').textContent=use>78?'Reduce rate, isolate a compartment, or run a calibrated geomechanical case.':`${state.faultState} all-fault set · ${projectCount} storage project${projectCount>1?'s':''}; unit-response screening remains provisional.`;renderChart(p)}
function renderChart(p){const w=320,h=165,left=34,right=10,top=12,bottom=25,years=[1,5,10,15,20,25,30,40,50,60],values=years.map(y=>pressureAt(p,y)),max=Math.max(state.limit,...values)*1.12,x=y=>left+(y/60)*(w-left-right),y=v=>top+(1-v/max)*(h-top-bottom);let svg='';[0,.5,1].forEach(f=>{const yy=top+f*(h-top-bottom),val=max*(1-f);svg+=`<line class="chart-grid" x1="${left}" y1="${yy}" x2="${w-right}" y2="${yy}"/><text class="chart-axis" x="2" y="${yy+3}">${fmt(val,0)}</text>`});svg+=`<line class="chart-limit" x1="${left}" y1="${y(state.limit)}" x2="${w-right}" y2="${y(state.limit)}"/><text class="chart-axis" x="${w-55}" y="${y(state.limit)-4}">limit</text>`;const line=years.map((yr,i)=>`${i?'L':'M'}${x(yr).toFixed(1)} ${y(values[i]).toFixed(1)}`).join('');svg+=`<path class="chart-area" d="${line}L${x(60)} ${h-bottom}L${left} ${h-bottom}Z"/><path class="chart-line" d="${line}"/>`;years.forEach((yr,i)=>svg+=`<circle class="chart-point" cx="${x(yr)}" cy="${y(values[i]).toFixed(1)}" r="3"/>`);[0,20,40,60].forEach(yr=>svg+=`<text class="chart-axis" x="${x(yr)-5}" y="${h-7}">${yr}</text>`);svg+=`<text class="chart-axis" x="${w-30}" y="${h-7}">year</text>`;els.chart.innerHTML=svg;$('chartPercentile').textContent=`P${state.percentile}`}
function layerLabels(){return{pressure:['Δp · bar','Pressure change'],margin:['Remaining · bar','Pressure margin'],geothermal:['Cost impact · %','Geothermal injection impact'],co2:['Gas saturation · %','CO₂ plume saturation'],depth:['Top depth · m','Reservoir top depth'],thickness:['Thickness · m','Gross reservoir thickness'],permeability:['Permeability · mD','Permeability'],porosity:['Porosity · %','Porosity']}[state.layer]}
function renderLegend(){const[lo,hi]=ranges(),labels=layerLabels(),geology=isGeologyLayer();$('legendLow').textContent=fmt(lo,state.layer==='porosity'?1:0);$('legendHigh').textContent=fmt(hi,state.layer==='porosity'?1:0);$('legendUnit').textContent=labels[0];$('legendRamp').style.background=`linear-gradient(90deg,${palettes[state.layer].join(',')})`;$('legendCaption').textContent=geology?(state.layer==='depth'?'Fixed structure · static scale':`Geology P${state.percentile} · static P10–P90 scale`):`P${state.percentile} · ${state.reservoir.is_opm_result?'OPM Flow ensemble':'analytical proxy'}`;$('mapTitle').textContent=geology?`${labels[1]} · ${state.layer==='depth'?'fixed':`P${state.percentile}`}`:`${labels[1]} · Year ${state.year}`}
function render(){if(!state.reservoir)return;$('rateOutput').textContent=`${state.rate.toFixed(1)} Mt/yr`;$('durationOutput').textContent=`${state.duration} yr`;$('yearOutput').textContent=`Year ${state.year}`;$('betaStatus').textContent=state.betaEnabled?`ACTIVE · ${state.betaRate} Mt/yr`:'OFF';$('zetaStatus').textContent=state.zetaEnabled?`ACTIVE · ${state.zetaRate} Mt/yr`:'OFF';$('faultCaption').textContent=`All ${state.context.faults.length} supplied faults · multiplier ${{open:'1.0',"semi-open":'0.05',closed:'0.0001'}[state.faultState]} · six vertical layers`;renderLegend();renderMap();renderDetail()}

els.reservoir.addEventListener('change',e=>selectReservoir(e.target.value));els.rate.addEventListener('input',e=>{state.rate=Number(e.target.value);render()});els.duration.addEventListener('input',e=>{state.duration=Number(e.target.value);render()});els.year.addEventListener('input',e=>{state.year=Number(e.target.value);render()});els.limit.addEventListener('change',e=>{state.limit=Math.max(1,Number(e.target.value));render()});document.querySelectorAll('.layer-button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.layer-button').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.layer=b.dataset.layer;render()}));document.querySelectorAll('.percentiles button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.percentiles button').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.percentile=Number(b.dataset.p);render()}));
$('basemapToggle').addEventListener('click',()=>{state.basemap=!state.basemap;$('basemapToggle').classList.toggle('active',state.basemap);$('basemapToggle').setAttribute('aria-pressed',String(state.basemap));$('basemapStatus').textContent=state.basemap?'Visible · roads and places':'Hidden';renderMap()});$('wellsToggle').addEventListener('click',()=>{state.showWells=!state.showWells;$('wellsToggle').classList.toggle('active',state.showWells);$('wellsToggle').setAttribute('aria-pressed',String(state.showWells));$('wellsStatus').textContent=state.showWells?`${state.context.legacy_wells.length} wells visible`:'Hidden';updateSceneLayer($('sceneWells'),state.showWells);renderMap()});$('faultsToggle').addEventListener('click',()=>{state.showFaults=!state.showFaults;$('faultsToggle').classList.toggle('active',state.showFaults);$('faultsToggle').setAttribute('aria-pressed',String(state.showFaults));$('faultsStatus').textContent=state.showFaults?`${state.context.faults.length} supplied traces`:'Hidden';updateSceneLayer($('sceneFaults'),state.showFaults);renderMap()});$('betaToggle').addEventListener('change',e=>{state.betaEnabled=e.target.checked;render()});$('betaRate').addEventListener('change',e=>{state.betaRate=Number(e.target.value);render()});$('zetaToggle').addEventListener('change',e=>{state.zetaEnabled=e.target.checked;render()});$('zetaRate').addEventListener('change',e=>{state.zetaRate=Number(e.target.value);render()});$('faultState').addEventListener('change',e=>{state.faultState=e.target.value;render()});
function setView(mode){state.viewMode=mode;document.querySelector('.map-canvas').classList.toggle('view-3d',mode==='3d');els.canvas3d.hidden=mode!=='3d';$('viewer3dUi').hidden=mode!=='3d';$('view2d').classList.toggle('active',mode==='2d');$('view3d').classList.toggle('active',mode==='3d');renderMap()}
$('view2d').addEventListener('click',()=>setView('2d'));$('view3d').addEventListener('click',()=>setView('3d'));$('fitButton').addEventListener('click',()=>{fitView();renderMap()});$('zoomIn').addEventListener('click',()=>zoomMap(-1));$('modelAssumptionsButton').addEventListener('click',()=>$('modelAssumptionsDialog').showModal());$('aboutButton').addEventListener('click',()=>$('aboutDialog').showModal());$('searchInput').addEventListener('input',e=>{const q=e.target.value.toLowerCase();if(q.includes('north'))state.selectedIndex=Math.floor(state.reservoir.points.length*.7);else if(q.includes('south'))state.selectedIndex=Math.floor(state.reservoir.points.length*.3);else if(/^\d+$/.test(q))state.selectedIndex=Math.min(state.reservoir.points.length-1,Math.max(0,Number(q)-1));render()});
els.map.addEventListener('wheel',e=>{e.preventDefault();const r=els.map.getBoundingClientRect(),h=mapHeight();zoomMap(e.deltaY<0?1:-1,{x:(e.clientX-r.left)/r.width*MAP_W,y:(e.clientY-r.top)/r.height*h})},{passive:false});els.map.addEventListener('pointerdown',e=>{els.map.setPointerCapture(e.pointerId);mapDrag={x:e.clientX,y:e.clientY,centre:world(state.view),cellIndex:e.target.classList.contains('model-cell')?Number(e.target.dataset.index):null};mapMoved=false});els.map.addEventListener('pointermove',e=>{if(!mapDrag)return;const r=els.map.getBoundingClientRect(),dx=(e.clientX-mapDrag.x)/r.width*MAP_W,dy=(e.clientY-mapDrag.y)/r.height*mapHeight();if(Math.abs(dx)+Math.abs(dy)>4)mapMoved=true;state.view={...unworld(mapDrag.centre.x-dx,mapDrag.centre.y-dy),zoom:state.view.zoom};renderMap()});els.map.addEventListener('pointerup',()=>{const cellIndex=mapDrag?.cellIndex;mapDrag=null;if(!mapMoved&&cellIndex!=null){state.selectedIndex=cellIndex;render()}setTimeout(()=>mapMoved=false,0)});els.map.addEventListener('pointercancel',()=>{mapDrag=null;mapMoved=false});window.addEventListener('resize',()=>state.reservoir&&renderMap());
function updateSceneLayer(button,enabled){button.classList.toggle('enabled',enabled);button.setAttribute('aria-pressed',String(enabled))}
function resetScene(){state.scene.yaw=-.72;state.scene.pitch=-.5;state.scene.scale=1;state.scene.verticalExaggeration=1.8;$('verticalExaggeration').value='1.8';$('verticalExaggerationValue').textContent='1.8×';render3d()}
let sceneDrag=null;els.canvas3d.addEventListener('pointerdown',e=>{els.canvas3d.setPointerCapture(e.pointerId);sceneDrag={x:e.clientX,y:e.clientY,yaw:state.scene.yaw,pitch:state.scene.pitch,moved:false}});els.canvas3d.addEventListener('pointermove',e=>{if(!sceneDrag)return;const dx=e.clientX-sceneDrag.x,dy=e.clientY-sceneDrag.y;if(Math.abs(dx)+Math.abs(dy)>2)sceneDrag.moved=true;state.scene.yaw=sceneDrag.yaw+dx*.008;state.scene.pitch=Math.max(-Math.PI/2,Math.min(.35,sceneDrag.pitch-dy*.006));render3d()});els.canvas3d.addEventListener('pointerup',e=>{if(sceneDrag&&!sceneDrag.moved&&state.scene.hitPoints){const r=els.canvas3d.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;let nearest=null,distance=Infinity;state.scene.hitPoints.forEach(p=>{const d=Math.hypot(p.x-x,p.y-y);if(d<distance){nearest=p;distance=d}});if(nearest&&distance<22){state.selectedIndex=nearest.index;render()}}sceneDrag=null});els.canvas3d.addEventListener('pointercancel',()=>sceneDrag=null);els.canvas3d.addEventListener('wheel',e=>{e.preventDefault();state.scene.scale=Math.max(.45,Math.min(2.8,state.scene.scale*(e.deltaY<0?1.1:.9)));render3d()},{passive:false});
$('sceneZoomIn').addEventListener('click',()=>{state.scene.scale=Math.min(2.8,state.scene.scale*1.15);render3d()});$('sceneZoomOut').addEventListener('click',()=>{state.scene.scale=Math.max(.45,state.scene.scale/1.15);render3d()});$('sceneTop').addEventListener('click',()=>{state.scene.yaw=0;state.scene.pitch=-Math.PI/2;render3d()});$('sceneReset').addEventListener('click',resetScene);$('sceneSurface').addEventListener('click',()=>{state.scene.showSurface=!state.scene.showSurface;updateSceneLayer($('sceneSurface'),state.scene.showSurface);render3d()});$('sceneFaults').addEventListener('click',()=>{state.showFaults=!state.showFaults;updateSceneLayer($('sceneFaults'),state.showFaults);$('faultsToggle').classList.toggle('active',state.showFaults);$('faultsToggle').setAttribute('aria-pressed',String(state.showFaults));$('faultsStatus').textContent=state.showFaults?`${state.context.faults.length} supplied traces`:'Hidden';render3d()});$('sceneWells').addEventListener('click',()=>{state.showWells=!state.showWells;updateSceneLayer($('sceneWells'),state.showWells);$('wellsToggle').classList.toggle('active',state.showWells);$('wellsToggle').setAttribute('aria-pressed',String(state.showWells));$('wellsStatus').textContent=state.showWells?`${state.context.legacy_wells.length} wells visible`:'Hidden';render3d()});$('verticalExaggeration').addEventListener('input',e=>{state.scene.verticalExaggeration=Number(e.target.value);$('verticalExaggerationValue').textContent=`${Number(e.target.value).toFixed(1)}×`;render3d()});

Promise.all([fetch('data/pressure-model.json?v=0.10.0',{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject(new Error('Pressure dataset failed to load'))),fetch('data/regional-context.json?v=0.10.0',{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject(new Error('Regional context failed to load')))]).then(([model,context])=>{state.model=model;state.context=context;$('wellsStatus').textContent=`${context.legacy_wells.length} wells visible`;$('faultsStatus').textContent=`${context.faults.length} supplied traces`;populateReservoirs()}).catch(error=>{$('engineLabel').textContent='Model unavailable';document.querySelector('.map-canvas').innerHTML=`<p style="padding:2rem;color:#d98b76">${error.message}</p>`});
